/**
 * Generates server/migrations/attempts_metadata_backfill.sql from the content manifests.
 * Re-run whenever activities are added or moved between modules:
 *   npx tsx scripts/build-attempt-backfill-sql.ts
 */
import fs from 'fs';
import path from 'path';
import { allActivityMetadata } from '../server/activityCatalog';

const rows = allActivityMetadata().map(
  ([id, m]) => `  ('${id.replace(/'/g, "''")}', '${m.subject}', ${m.moduleId}, ${m.grade})`
);

const sql = `-- GENERATED by scripts/build-attempt-backfill-sql.ts from src/content/class-*/*/module-*/activities.json.
-- Do not edit by hand. Idempotent: only rows whose metadata differs from the manifests are touched.
-- ${rows.length} activities.
UPDATE attempts AS a
SET subject = m.subject, module_id = m.module_id, grade = m.grade
FROM (VALUES
${rows.join(',\n')}
) AS m(activity_id, subject, module_id, grade)
WHERE a.activity_id = m.activity_id
  AND (a.subject IS DISTINCT FROM m.subject
    OR a.module_id IS DISTINCT FROM m.module_id
    OR a.grade IS DISTINCT FROM m.grade);
`;

const out = path.resolve(process.cwd(), 'server', 'migrations', 'attempts_metadata_backfill.sql');
fs.writeFileSync(out, sql, 'utf8');
console.log(`Wrote ${out} (${rows.length} activities)`);
